class DesktopAssets {
    fun open(path: String): InputStream =
        DesktopAssets::class.java.getResourceAsStream("/" + path.removePrefix("/"))
            ?: error("missing resource $path")
}

object DesktopLog {
    fun d(tag: String, message: String) = i(tag, message)
    fun i(tag: String, message: String) = println("I/$tag $message")
    fun w(tag: String, message: String, error: Throwable? = null) = write("W", tag, message, error)
    fun e(tag: String, message: String, error: Throwable? = null) = write("E", tag, message, error)

    private fun write(level: String, tag: String, message: String, error: Throwable?) {
        System.err.println("$level/$tag $message")
        error?.printStackTrace()
    }
}

/** Android's OpenDocument contract. Desktop asks with a file dialog. */
fun chooseDesktopDocument(deliver: (ByteArray) -> Unit) {
    val chooser = JFileChooser()
    chooser.fileFilter = FileNameExtensionFilter("Extension", "zip", "crx")
    if (chooser.showOpenDialog(null) == JFileChooser.APPROVE_OPTION) {
        deliver(chooser.selectedFile.readBytes())
    }
}

