/** Android sends mailto, tel, sms, and market to another app. */
fun launchDesktopAddress(raw: String): Boolean {
    val uri = try {
        URI(raw.trim())
    } catch (_: Exception) {
        return false
    }
    val scheme = uri.scheme?.lowercase() ?: return false
    if (scheme !in setOf("mailto", "tel", "sms", "market")) return false
    val desktop = Desktop.getDesktop()
    return try {
        when (scheme) {
            "mailto" -> desktop.mail(uri)
            else -> desktop.browse(uri)
        }
        true
    } catch (_: Exception) {
        false
    }
}

/**
 * Desktop form of a stationary two-finger double tap.
 * A trackpad middle-click double tap does not consume the event.
 */
@Composable
fun desktopRingGesture(onRing: () -> Unit) {
    DisposableEffect(onRing) {
        val listener = AWTEventListener { event ->
            val mouse = event as? MouseEvent ?: return@AWTEventListener
            val tapped = mouse.id == MouseEvent.MOUSE_CLICKED &&
                mouse.button == MouseEvent.BUTTON2 &&
                mouse.clickCount == 2
            if (tapped) onRing()
        }
        val toolkit = Toolkit.getDefaultToolkit()
        toolkit.addAWTEventListener(listener, AWTEvent.MOUSE_EVENT_MASK)
        onDispose { toolkit.removeAWTEventListener(listener) }
    }
}

/** Android's system back. Desktop uses Escape and does not steal the key otherwise. */
@Composable
fun desktopBackHandler(enabled: Boolean, onBack: () -> Unit) {
    DisposableEffect(enabled, onBack) {
        val listener = KeyEventDispatcher { event ->
            val back = enabled &&
                event.id == KeyEvent.KEY_PRESSED &&
                event.keyCode == KeyEvent.VK_ESCAPE
            if (back) onBack()
            back
        }
        val manager = KeyboardFocusManager.getCurrentKeyboardFocusManager()
        manager.addKeyEventDispatcher(listener)
        onDispose { manager.removeKeyEventDispatcher(listener) }
    }
}

/** Public Downloads on Android. Desktop writes into the user's Downloads directory. */
fun desktopDownloadFile(suggestedName: String): File {
    val dir = File(System.getProperty("user.home"), "Downloads")
    dir.mkdirs()
    val clean = suggestedName.substringAfterLast('/').substringAfterLast('\\').ifBlank { "download" }
    return File(dir, clean)
}

fun installDesktopDownloads(client: KCEFClient) {
    client.addDownloadHandler(object : CefDownloadHandlerAdapter() {
        override fun onBeforeDownload(
            browser: CefBrowser,
            downloadItem: CefDownloadItem,
            suggestedName: String,
            callback: CefBeforeDownloadCallback,
        ) {
            val name = suggestedName.ifBlank { downloadItem.suggestedFileName ?: "download" }
            callback.Continue(desktopDownloadFile(name).absolutePath, false)
        }
    })
}

/**
 * File chooser, camera, and microphone.
 * Android registers these on the WebChrome client. Desktop registers them on the Chromium client.
 * Geolocation stays Chromium's own prompt; this build of JCEF does not deliver that request.
 */
fun installDesktopPagePrompts(client: KCEFClient) {
    client.addDialogHandler(object : CefDialogHandler {
        override fun onFileDialog(
            browser: CefBrowser,
            mode: CefDialogHandler.FileDialogMode,
            title: String,
            defaultFilePath: String,
            acceptFilters: Vector<String>,
            callback: CefFileDialogCallback,
        ): Boolean {
            SwingUtilities.invokeLater {
                val chooser = JFileChooser()
                val save = mode == CefDialogHandler.FileDialogMode.FILE_DIALOG_SAVE
                val result = if (save) chooser.showSaveDialog(null) else chooser.showOpenDialog(null)
                if (result == JFileChooser.APPROVE_OPTION) {
                    val chosen = Vector<String>()
                    chosen.add(chooser.selectedFile.absolutePath)
                    callback.Continue(chosen)
                } else {
                    callback.Cancel()
                }
            }
            return true
        }
    })
    client.addPermissionHandler(object : CefPermissionHandler {
        override fun onRequestMediaAccessPermission(
            browser: CefBrowser,
            frame: CefFrame,
            requestingUrl: String,
            requestedPermissions: Int,
            callback: CefMediaAccessCallback,
        ): Boolean {
            SwingUtilities.invokeLater {
                val choice = JOptionPane.showConfirmDialog(
                    null,
                    "Allow this page to use the camera and microphone?\n$requestingUrl",
                    "Permission",
                    JOptionPane.OK_CANCEL_OPTION,
                )
                if (choice == JOptionPane.OK_OPTION) callback.Continue(requestedPermissions)
                else callback.Cancel()
            }
            return true
        }
    })
}

